+        methodWriter.dupX1();
+        methodWriter.invokeInterface(WriterConstants.COLLECTION_TYPE, WriterConstants.COLLECTION_SIZE);
+        methodWriter.visitInsn(Opcodes.IADD);
+        methodWriter.mark(noFlip);
+    }
