+            // transform should only rewrite documents that require it
+            assertThat(
+                "Ingest run: "
+                    + XContentMapValues.extractValue(INGEST_RUN_FIELD, source)
+                    + " did not match max run: "
+                    + XContentMapValues.extractValue(MAX_RUN_FIELD, source)
+                    + ", iteration: "
+                    + iteration,
